package main

import (
	"fmt"

	"charm.land/huh/v2"
)

func main() {
	slugs := []string{
		"entireio/cli",
		"entirehq/company-knowledge",
		"entirehq/entire.io",
		"entireio/entire.nvim",
		"entirehq/entiredb",
		"entirehq/ephemera",
		"entirehq/ferrata",
		"entirehq/fleet",
	}
	options := make([]huh.Option[string], 0, len(slugs))
	for _, s := range slugs {
		options = append(options, huh.NewOption(s, s))
	}
	var selected []string
	form := huh.NewForm(
		huh.NewGroup(
			huh.NewMultiSelect[string]().
				Title("Repos").
				Description("Press / to filter. Up to 5 repos.").
				Filterable(true).
				OptionsFunc(func() []huh.Option[string] {
					return options
				}, nil).
				Value(&selected),
		),
	).WithTheme(huh.ThemeFunc(huh.ThemeDracula))
	if err := form.Run(); err != nil {
		fmt.Println("err:", err)
	}
	fmt.Println("selected:", selected)
}

