func newLazyOptions(loader func() []huh.Option[string]) func() []huh.Option[string] {
	var (
		once    sync.Once
		options []huh.Option[string]
	)
	return func() []huh.Option[string] {
		once.Do(func() {
			options = loader()
		})
		return options
	}
}

